    "rocket_equation": "Équation de la fusée",
    "tsiolkovsky_s_speed_rocket": "Celle de Tsiolkovski : la vitesse qu’une fusée gagne en brûlant son carburant, selon sa vitesse d’éjection v<sub>e</sub>, ou son impulsion spécifique I<sub>sp</sub>, et sa masse pleine, m<sub>0</sub>, et vide, m<sub>f</sub> ; sa vitesse tracée au fil de la combustion. Avec la durée de combustion, sa poussée, son accélération au début et à la fin, et le Δv restant en montant à la verticale contre g. L’I<sub>sp</sub> d’un moteur au kérosène est d’environ 300 s, d’un moteur à hydrogène 450 ; la mise en orbite demande environ 9400 m/s.",
