    "v_f_standing_waves": "v = fλ, les ondes stationnaires de cordes et de tuyaux, les battements, les lentilles et miroirs, la formule des opticiens, la réfraction et l’angle critique, les interférences par deux fentes ou un réseau, une fente simple et la résolution d’une lentille, la polarisation, l’effet Doppler du son et de la lumière, la lumière et les photons, et le son en décibels.",
    "matter": "Matière",
    "heat_q_mc_t": "Chaleur : Q = mcΔT à partir de trois valeurs, la chaleur latente, le mélange, la dilatation thermique, la conduction, le rayonnement, le refroidissement de Newton, le point de rosée, les vitesses des molécules de gaz, un gaz parfait en isotherme, isobare, isochore ou adiabatique, et les machines thermiques. Solides : contrainte et déformation. Fluides : masse volumique, pression, pression en profondeur, poussée d’Archimède, écoulement dans un tuyau, nombre de Reynolds avec le frottement d’un tuyau, et loi de Stokes.",
    "modern": "Moderne",
    "e_mc_binding_energy": "E = mc², l’énergie de liaison, le bilan Q d’une réaction, l’effet photoélectrique, les longueurs d’onde de de Broglie, le principe d’incertitude, une particule dans une boîte, la diffusion Compton, l’effet tunnel, la relativité restreinte, les raies de l’hydrogène et les orbites de Bohr, et la décroissance radioactive.",
    "biology": "Biologie",
    "genetics_from_punnett_squares": "La génétique, des échiquiers de Punnett aux cartes de gènes et au risque génétique ; l’ADN et l’ARN, traduits, alignés, avec amorces, ARN guides CRISPR et gels ; protéines et enzymes ; dilutions, numérations et qPCR de laboratoire ; cellules ; santé ; et écologie et évolution. Cliquez sur un nombre pour l’insérer.",
    "close_biology": "Fermer la biologie",
    "genetics": "Génétique",
    "punnett_squares_of_up": "Des échiquiers de Punnett jusqu’à six gènes, tracés, et du chromosome X ; Hardy-Weinberg, d’après p, d’après des effectifs avec son test du χ², ou d’après le caractère récessif ; le χ² d’un croisement ; des cartes de gènes pour deux ou trois gènes, le chromosome tracé ; les probabilités de la descendance ; l’héritabilité, par l’équation de l’éleveur ; l’épistasie et la proportion qui convient ; le risque génétique, la famille tracée en arbre généalogique ; et les groupes sanguins.",
    "sequence_s_length_bases": "La longueur d’une séquence, ses bases, son GC le long de celle-ci et sa masse, avec son complément et son complément inverse ; la traduction dans six cadres et les cadres ouverts de lecture, tracés ; la roue des codons ; la T<sub>m</sub> d’une amorce par les plus proches voisins, leur fusion tracée ; l’ADN et l’ARN par A<sub>260</sub> et leur pureté ; masse, moles et copies ; la ligature, le plasmide tracé ; les digestions de restriction migrées sur un gel ; les copies de PCR, cycle par cycle ; les alignements, global et local, avec un nuage de points ; les ARN guides CRISPR ; les motifs avec les codes IUPAC ; les amorces pour la mutagenèse et l’assemblage de Gibson ; et les génomes et leurs copies.",
    "protein_s_mass_pi": "La masse, le pI, la charge, l’extinction et l’hydropathie d’une protéine, tracés ; les vingt acides aminés, le titrage de chacun tracé ; la concentration de protéine par A<sub>280</sub> ou une courbe d’étalonnage ; la cinétique enzymatique, de V<sub>max</sub> et K<sub>m</sub> ou ajustée à des points, avec inhibiteurs et le graphe de Lineweaver-Burk ; la liaison par Hill ; la dose-réponse, son IC<sub>50</sub> ajustée ; et un tableau de purification.",
    "lab": "Laboratoire",
    "c_v_c_v": "C₁V₁ = C₂V₂ et les dilutions en série, leurs tubes tracés ; préparer une solution, d’après sa molarité, sa formule, un pourcentage ou une solution mère ; la numération cellulaire ; la croissance et le doublement, et l’OD<sub>600</sub> ; les colonies et UFC/mL ; les tr/min et g de la centrifugeuse ; un mélange maître PCR ; la qPCR par ΔΔCt et sa courbe d’étalonnage ; la moyenne ± 2 ES avec barres d’erreur ; le R<sub>f</sub> de la chromatographie ; le microscope ; les tailles d’après un gel ; l’efficacité de transformation ; l’ensemencement de plaques ; la MOI ; les radioisotopes ; et les tampons.",
    "water_potential_osmolarity_and": "Le potentiel hydrique, l’osmolarité et la tonicité, un globule rouge tracé ; le rapport surface/volume ; le Q₁₀ ; la diffusion par Fick ; les potentiels de membrane par Nernst et par Goldman ; l’énergie libre ; le débit cardiaque et la pression artérielle, tracés ; et la respiration, son ATP et le quotient respiratoire.",
    "health": "Santé",
    "diagnostic_tests_their_sensitivity": "Les tests diagnostiques, leur sensibilité, leur spécificité et leurs valeurs prédictives, mille personnes tracées ; le risque et les odds ratios avec leurs intervalles, et le nombre nécessaire à traiter ; une épidémie par SIR et l’immunité collective ; l’oxygène et l’hémoglobine, le décalage de Bohr tracé ; un potentiel d’action par Hodgkin et Huxley ; les reins, le DFGe et la clairance ; l’IMC et l’énergie ; et les concentrations d’un médicament au fil des doses. Pour apprendre, pas pour soigner.",
    "ecology": "Écologie",
    "population_growth_exponential_and": "La croissance d’une population, exponentielle et logistique ; prédateurs et proies par Lotka et Volterra ; capture-recapture ; la diversité par Simpson et Shannon ; les tables de survie et la survie ; les pyramides énergétiques ; la productivité primaire ; la sélection naturelle et la dérive génétique, génération par génération ; les matrices de Leslie ; la compétition ; espèces, aire et raréfaction ; les arbres par UPGMA et neighbour joining ; et l’horloge moléculaire.",
    "opens_card_of_physics": "Ouvre la fiche du panneau Physique qui calcule cela, avec ce que vous y avez saisi : là, n’importe laquelle de ses lettres à partir des autres.",
    "opens_card_of_finance": "Ouvre la fiche de l’onglet Finance de Résoudre qui calcule cela, avec ce que vous y avez saisi, et ce qu’elle donne en plus.",
    "opens_card_of_biology": "Ouvre la fiche du panneau Biologie qui calcule cela, avec ce que vous y avez saisi, et la trace.",
    "elastic": "Élastique",
    "they_bounce_apart_as": "Elles rebondissent l’une sur l’autre, comme des boules de billard, sans perte d’énergie cinétique.",
    "they_go_on_as": "Elles repartent d’un seul bloc : la quantité de mouvement est conservée, et le maximum d’énergie cinétique possible est perdu.",
