    "all_118_elements_point": "Les 118 éléments. Pointez-en un pour le voir au-dessus du tableau, cliquez dessus pour tout ce que l’on sait de lui et son atome ; les touches fléchées passent de l’un au suivant.",
    "molar_mass_of_formula_2": "La masse molaire d’une formule et la part de chaque élément ; grammes, moles et particules ; et la formule brute et moléculaire d’une composition.",
    "equation_balanced_with_kind": "Une équation équilibrée, avec son type et ce qu’elle oxyde et réduit ; les quantités d’une réaction, son réactif limitant et son rendement en pourcentage ; une feuille d’exercices ; la chaleur, q = mcΔT ; et la demi-vie.",
    "solutions": "Solutions",
    "molarity_dilution_freezing_and": "Molarité, dilution, points de congélation et d’ébullition d’une solution, pH, pOH, [H⁺] et [OH⁻], acides et bases faibles, tampons, et ce qui se dissout dans l’eau.",
    "common_ions_monatomic_and": "Les ions courants, monoatomiques et polyatomiques : la charge et la masse molaire de chacun, sa couleur dans l’eau et dans une flamme ; le nom d’une formule et la formule d’un nom ; et les nombres d’oxydation.",
    "ideal_gas_law_pv": "La loi des gaz parfaits, PV = nRT, avec la masse et la masse volumique d’un gaz ; la loi des gaz combinée ; les pressions partielles ; un gaz recueilli sur l’eau ; les volumes des gaz d’une réaction ; l’effusion ; l’air selon l’altitude ; et la vitesse du son.",
