    "how_strongly_atom_pulls": "La force avec laquelle son atome attire les électrons d’une liaison, sur l’échelle de Pauling, de 0.79 pour le césium à 3.98 pour le fluor. Les gaz nobles, avec peu de liaisons, n’en ont pas.",
