    "thermal_conductivity": "Conductivité thermique",
    "how_well_heat_flows": "La facilité avec laquelle la chaleur le traverse : des watts à travers un mètre pour chaque kelvin entre ses extrémités, sur un mètre carré. L’argent et le cuivre le plus, les gaz le moins.",
    "electrical_resistivity": "Résistivité électrique",
    "how_much_resists_current": "À quel point il résiste à un courant, à 20 °C : R = ρL/A. Faible pour les métaux, 1.6 × 10⁻⁸ Ω·m pour l’argent, le plus faible ; énorme pour un isolant comme le soufre.",
