    "magnetism": "Magnétisme",
    "how_acts_in_magnetic": "Son comportement dans un champ magnétique : ferromagnétique, comme le fer, un aimant lui-même ; paramagnétique, faiblement attiré ; diamagnétique, faiblement repoussé ; antiferromagnétique, le magnétisme de ses atomes s’annulant.",
    "crystal_structure": "Structure cristalline",
    "how_atoms_packed_in": "Comment ses atomes sont empilés dans le solide, à température ambiante. Dessous, sa maille élémentaire, la plus petite boîte qui se répète, ou pour une hexagonale un prisme de 3 ; ses atomes comptés selon leur part : un à un coin est partagé par 8 boîtes, ou 6 prismes, sur une face par 2. Boules grises : seulement son réseau, plusieurs atomes à chaque point.",
    "abundance_in_crust": "Abondance dans la croûte",
    "how_much_of_earth": "La part de la croûte terrestre qu’il représente, en mg/kg, parties par million en masse : l’oxygène près de la moitié, puis le silicium. Traces seulement : quelques atomes à la fois, formés dans les minerais d’uranium et de thorium ; synthétique : produit seulement en laboratoire.",
    "appearance": "Aspect",
    "what_looks_like_pure": "Son aspect, pur, à température ambiante.",
    "light_of_atoms_as": "La lumière de ses atomes à l’état gazeux, du violet à 380 nm au rouge à 750 : absorption, de la lumière blanche qui le traverse, des raies sombres sur l’arc-en-ciel là où il retire des couleurs ; émission, chauffé ou dans une étincelle, ces mêmes couleurs seules, brillantes sur fond noir. Chaque élément a ses propres raies, comme une empreinte : c’est ainsi que l’hélium a été trouvé dans le Soleil avant la Terre. Ses raies les plus fortes, telles que les liste le NIST, plus larges quand plus fortes ; pour un élément dont l’atome n’en a pas ici, celles de son ion. Cliquez : l’autre.",
