    "actinium_to_lawrencium_filling": "De l’actinium au lawrencium, remplissant la sous-couche 5f : tous radioactifs ; seuls le thorium et l’uranium sont courants dans la nature.",
    "draws_up_to_25": "Trace jusqu’à 25 fonctions de x, avec un curseur pour toute autre lettre, comme a dans a x^2 + b : x^2 – 3, 2sin(x) ; des suites, a(n) = a(n – 1) + 2 {a(1) = 1} ; et des champs de pentes, dy/dx = x – y {y(0) = 1}, un clic ajoutant une solution. Marque les racines, maximums, minimums et intersections. Faites glisser pour déplacer, molette ou pincement pour zoomer ; pointez une courbe pour ses valeurs, cliquez pour sa tangente. L’onglet Tableau les liste.",
