    "root_first_then_number": "La racine d’abord, puis le nombre, comme on l’écrit : 4 <sup>x</sup>√y 81 = 3, la racine 4e de 81. Pressée en premier, une racine à deux cases vides apparaît : saisissez la racine, Entrée passe à la case suivante ; les flèches et Tab vont de l’une à l’autre, ou cliquez sur une case pour y saisir. Les racines impaires de nombres négatifs fonctionnent : 3 <sup>x</sup>√y –8 = –2.",
    "times_ten_to_power": "Fois dix puissance le nombre suivant : 5 EE 3 = 5000, 5 × 10<sup>3</sup>. Pressée en premier, elle apparaît comme deux cases à remplir : Entrée passe à la suivante, les flèches et Tab vont de l’une à l’autre, ou cliquez sur l’une.",
