    "page": "Page",
    "open_mode": "Mode d’ouverture",
    "what_toolbar_icon_and": "Ce qu’ouvrent l’icône de la barre d’outils et Alt+S : Fixe, la fenêtre sous l’icône ; Détaché, la calculatrice dans sa propre fenêtre, qui s’agrandit ou se réduit avec elle ; ou Avancé, la calculatrice détachée dans une grande fenêtre avec les outils sur son côté, dont le bouton Rattacher la ramène en mode Détaché. Lancer ouvre le mode choisi ; les modes Détaché et Avancé sont aussi dans le menu de l’icône, et le mode Détaché sur le bouton de la page.",
    "fixed": "Fixe",
    "detached": "Détaché",
