    "and_tanh": " et tanh",
    "also_changes_ln_to": "). Elle change aussi ln en log",
    "to_2_2": "en 2",
    "log_to_10": ", log en 10",
    "to_e_y": ", π en e, y",
    "to_log": "en log",
    "to_5": "√ en",
    "y_and": "√y, et %,",
    "abs_x_and_rand": ", abs, x! et Rand en mod, gcd, lcm, floor, ceil et round. Cliquez",
    "again_to_return_buttons": "de nouveau pour rendre aux boutons leurs fonctions d’origine.",
    "opens_parenthetical_expression_expressions": "[(] Ouvre une expression entre parenthèses. Les expressions peuvent être imbriquées. Un clic dessus fait apparaître un anneau autour du bouton pour vous indiquer qu’une expression entre parenthèses est encore active (jusqu’à ce que toutes les expressions soient fermées par la parenthèse fermante ou le signe égal).",
    "number_right_before_parenthesis": "Un nombre juste avant la parenthèse est multiplié : 5 ( 2 + 3 ) vaut 5 × (2 + 3).",
    "closes_parenthetical_expression_ring": "[)] Ferme une expression entre parenthèses. L’anneau autour de la touche de parenthèse ( reste jusqu’à ce que toutes les expressions soient fermées avec cette touche ou après un clic sur le signe égal.",
    "calculates_percentages_adds_markups": "[%] Calcule des pourcentages, ajoute des majorations et soustrait des remises. Seule, elle divise la valeur par 100 : 50 % donne 0.5. Par exemple, pour calculer 8 % de 500, saisissez 8 % × 500 = qui donne 40.",
    "to_add_markup_or": "Pour ajouter une majoration ou soustraire une remise, utilisez-la après la touche + ou –. Par exemple, pour calculer le coût total d’un article à 500 $ avec une taxe de vente de 8 %, saisissez 500 + 8 % = qui donne 540.",
    "or_h_1_returns": "[\\ ou h, 1] Donne l’inverse d’une valeur en format décimal.",
    "h_2_squares_value": "[h, 2] Élève une valeur au carré.",
    "h_3_cubes_value": "[h, 3] Élève une valeur au cube.",
    "or_or_click_between": "[^ ou ' ou \"] Cliquez entre deux valeurs pour élever la première à la puissance de la seconde.",
    "for_example_to_compute": "Par exemple, pour calculer 3",
    "enter_3_y": ", saisissez 3 y",
    "4_which_returns_81": "4 = qui donne 81.",
    "h_logarithm_to_any": "[h, ^] Le logarithme en n’importe quelle base : saisissez le nombre, puis log",
