    "x_calculates_factorial_of": "[x] Calcule la factorielle d’une valeur : les nombres entiers de 0 à 170, et les décimales aussi (2.5! donne 3.32335…).",
    "shift_r_or_h": "[Maj+R ou h, r] Calcule la racine carrée d’une valeur : √ 16 donne 4.",
    "h_shift_r_calculates": "[h, Maj+R] Calcule la racine cubique d’une valeur, comme",
    "y_with_3_undoes": "√y avec 3 ; elle annule x",
    "cube_roots_of_negative": ". Les racines cubiques de nombres négatifs fonctionnent aussi :",
    "8_returns_2": "√-8 donne -2.",
    "r_root_first_then": "[r] La racine d’abord, puis le nombre, comme on l’écrit. Par exemple, pour calculer",
    "enter_4": "saisissez 4",
    "y_81_which_returns": "√y 81 = qui donne 3. Les racines impaires de nombres négatifs fonctionnent aussi :",
    "8_returns_2_available": "√-8 donne -2. (Disponible quand le",
    "button_clicked_on": "bouton est cliqué, sur",
    "shift_l_returns_log": "[Maj+L] Donne le logarithme décimal d’une valeur.",
    "h_shift_l_calculates": "[h, Maj+L] Calcule 10 à la puissance d’une valeur : 10",
    "1000_undoes_log_available": "vaut 1000. Elle annule log. (Disponible quand le",
