    "c_calculates_cosine_of": "[c] Calcule le cosinus d’une valeur.",
    "shift_v_calculates_arc": "[Maj+V] Calcule l’arc cosinus d’une valeur. (Disponible quand le",
    "t_calculates_tangent_of": "[t] Calcule la tangente d’une valeur.",
